//! Twin of the `pickle` suites in `laila-js/tests/vectors/codecs.test.js`:
//! `codecs.json` (generated by the real CPython 3.14 / numpy 2.3) is the oracle.

mod fixture;

use fixture::{case, cases, decode, first_diff, fixture, ndarray, ndarrays};
use laila::_codecs::pickle::{dumps, loads, protocol_of, DEFAULT_PROTOCOL, HIGHEST_PROTOCOL};
use laila::prelude::*;

fn payload(name: &str, key: &str) -> Option<Vec<u8>> {
    fixture()["cases"][name]
        .get(key)
        .and_then(|v| v.as_str())
        .map(decode)
}

/// `describe("pickle protocol 5")`: every fixture case with a `pickle` payload
/// and no `npy` key round-trips byte-exactly.
#[test]
fn pickle_protocol_5_fixture_cases() {
    let all = cases();
    let obj = fixture()["cases"].as_object().unwrap();
    let mut checked = 0;
    let expected = obj
        .values()
        .filter(|r| r.get("pickle").is_some() && r.get("npy").is_none())
        .count()
        - 1;
    for (name, r) in obj {
        if r.get("pickle").is_none() || r.get("npy").is_some() {
            continue;
        }
        if name == "str_surrogate" {
            continue; // a lone surrogate cannot live in a Rust `str` (documented skip)
        }
        let (_, value) = all
            .iter()
            .find(|(n, _)| n == name)
            .unwrap_or_else(|| panic!("missing Rust construction for {name}"));
        let want = payload(name, "pickle").unwrap();
        let got = dumps(value, None).unwrap_or_else(|e| panic!("{name}: dumps raised {e}"));
        assert!(got == want, "{name}: {}", first_diff(&got, &want));
        let back = loads(&want).unwrap_or_else(|e| panic!("{name}: loads raised {e}"));
        if name == "float_nan" {
            assert!(
                matches!(back, Arg::Float(f) if f.is_nan()),
                "{name}: {back:?}"
            );
        } else {
            assert!(
                back == *value,
                "{name}: roundtrip gave {}",
                &back.__repr__()[..back.__repr__().len().min(120)]
            );
        }
        checked += 1;
    }
    assert_eq!(
        checked, expected,
        "every non-ndarray pickle case except str_surrogate must be checked"
    );
}

/// `str_surrogate` has no Rust twin: the payload still decodes to *something*
/// deterministic (an error, since Rust strings cannot hold lone surrogates).
#[test]
fn str_surrogate_is_a_unicode_decode_error() {
    let want = payload("str_surrogate", "pickle").unwrap();
    let err = loads(&want).unwrap_err();
    assert_eq!(err.kind, ExcKind::UnicodeDecodeError);
}

/// `describe("npy ...")`, pickle half: `ndarray.__reduce_ex__` for protocol 5
/// (`_frombuffer`) and protocol 4 (`_reconstruct` + BUILD).
#[test]
fn ndarray_pickles() {
    for (name, nd) in ndarrays() {
        let arr = nd.clone().into_arg();
        for (key, proto) in [("pickle", 5), ("pickle4", 4)] {
            let Some(want) = payload(&name, key) else {
                continue;
            };
            let got = dumps(&arr, Some(proto))
                .unwrap_or_else(|e| panic!("{name} {key}: dumps raised {e}"));
            assert!(got == want, "{name} {key}: {}", first_diff(&got, &want));
            let back = loads(&want).unwrap_or_else(|e| panic!("{name} {key}: loads raised {e}"));
            let back = back
                .as_ndarray()
                .unwrap_or_else(|| panic!("{name} {key}: loads gave {}", back.type_name()));
            assert_eq!(back.dtype, nd.dtype, "{name} {key}");
            assert_eq!(back.fortran_order, nd.fortran_order, "{name} {key}");
            assert!(
                back.array_equal(&nd, true),
                "{name} {key}: {}",
                back.__repr__()
            );
        }
    }
}

#[test]
fn ndarray_shared_and_nested() {
    // Two references to one array: the second is a BINGET; the dtype and the
    // `b'b'` constant are memo hits as well.
    let a = ndarray("npy_f64").into_arg();
    let lst: Arg = vec![a.clone(), a.clone(), ndarray("npy_i32").into_arg()].into_arg();
    for proto in [4, 5] {
        let p = dumps(&lst, Some(proto)).unwrap();
        let back = loads(&p).unwrap();
        let items = back.__iter__().unwrap();
        assert_eq!(items.len(), 3);
        assert!(
            items[0].is(&items[1]),
            "shared array must come back as one object"
        );
        assert!(items[0]
            .as_ndarray()
            .unwrap()
            .array_equal(&ndarray("npy_f64"), true));
        assert!(items[2]
            .as_ndarray()
            .unwrap()
            .array_equal(&ndarray("npy_i32"), true));
        assert_eq!(items[2].as_ndarray().unwrap().dtype, "<i4");
    }
    // nested in a dict value
    let d = dict(Args::new()).unwrap();
    d.__setitem__("arr", ndarray("npy_be_f8_fortran").into_arg())
        .unwrap();
    let back = loads(&dumps(&d, Some(4)).unwrap()).unwrap();
    let arr = back.__getitem__("arr").unwrap();
    let arr = arr.as_ndarray().unwrap();
    assert_eq!(arr.dtype, ">f8");
    assert!(arr.fortran_order);
    assert!(arr.array_equal(&ndarray("npy_be_f8_fortran"), true));
}

/// CPython 3.14: `pickle.dumps(list(range(100000)))` commits a frame at the
/// first opcode boundary after it reaches 64 KiB (`_Pickler_OpcodeBoundary`).
#[test]
fn framing_splits_large_output_like_cpython() {
    let lst: Arg = (0..100000i64).collect::<Vec<_>>().into_arg();
    let p = dumps(&lst, None).unwrap();
    let mut frames = Vec::new();
    let mut pos = 2usize;
    while pos < p.len() {
        assert_eq!(p[pos], 0x95, "FRAME expected at {pos}");
        let len = u64::from_le_bytes(p[pos + 1..pos + 9].try_into().unwrap()) as usize;
        frames.push((pos, len));
        pos += 9 + len;
    }
    assert_eq!(
        frames,
        vec![
            (2, 65537),
            (65548, 65537),
            (131094, 65536),
            (196639, 65536),
            (262184, 65536),
            (327729, 41193)
        ]
    );
    assert!(loads(&p).unwrap() == lst);
    // dict / tuple / set variants (also measured on CPython 3.14)
    let d = dict(Args::new()).unwrap();
    for i in 0..100000i64 {
        d.__setitem__(i, i).unwrap();
    }
    let p = dumps(&d, None).unwrap();
    assert_eq!(u64::from_le_bytes(p[3..11].try_into().unwrap()), 65537);
    let t = Arg::Tuple((0..100000i64).map(Arg::Int).collect::<Vec<_>>().into());
    let p = dumps(&t, None).unwrap();
    assert_eq!(u64::from_le_bytes(p[3..11].try_into().unwrap()), 65538);
}

/// `pickle.dumps(["", ""])`: the empty string is a singleton in CPython, so
/// the second occurrence is a BINGET (`\x80\x05\x95\n\x00..]\x94(\x8c\x00\x94h\x01e.`).
#[test]
fn empty_string_is_memoized() {
    let lst: Arg = vec![Arg::from(""), Arg::from("")].into_arg();
    let p = dumps(&lst, None).unwrap();
    assert_eq!(
        p,
        b"\x80\x05\x95\x0a\x00\x00\x00\x00\x00\x00\x00]\x94(\x8c\x00\x94h\x01e."
    );
    assert!(loads(&p).unwrap() == lst);
}

#[test]
fn large_bytes_are_written_outside_frames() {
    // CPython: [b"x"*70000, 1, 2] -> no frame header for the 3-byte prefix,
    // BINBYTES outside any frame, then a 7-byte trailing frame at 70010.
    let lst: Arg = vec![
        laila::python::object::bytes(vec![b'x'; 70000]),
        Arg::Int(1),
        Arg::Int(2),
    ]
    .into_arg();
    let p = dumps(&lst, None).unwrap();
    assert_eq!(&p[..5], b"\x80\x05]\x94(");
    assert_eq!(p[5], b'B');
    assert_eq!(p[70010], 0x95);
    assert_eq!(u64::from_le_bytes(p[70011..70019].try_into().unwrap()), 7);
    assert_eq!(p.len(), 70026);
    assert!(loads(&p).unwrap() == lst);
    // bytearray >= 64 KiB: BYTEARRAY8 header + payload outside the frame
    let ba = bytearray(args!(laila::python::object::bytes(vec![7u8; 70000]))).unwrap();
    let p = dumps(&ba, None).unwrap();
    assert_eq!(&p[..3], b"\x80\x05\x96");
    assert_eq!(p.len(), 2 + 9 + 70000 + 2);
    assert!(loads(&p).unwrap() == ba);
}

#[test]
fn complex_round_trips_via_builtins_complex() {
    let c = fixture::complex(1.5, -2.0);
    let p = dumps(&c, None).unwrap();
    // STACK_GLOBAL builtins.complex, (1.5, -2.0), REDUCE
    assert!(p.windows(8).any(|w| w == b"builtins"));
    assert!(p.windows(7).any(|w| w == b"complex"));
    assert!(loads(&p).unwrap() == c);
    let p4 = dumps(&c, Some(4)).unwrap();
    assert!(loads(&p4).unwrap() == c);
}

#[test]
fn protocol_4_builtin_containers() {
    // sets / frozensets / bytearrays via their protocol-4 forms (EMPTY_SET,
    // FROZENSET, builtins.bytearray REDUCE) all round-trip.
    for name in [
        "set_123",
        "set_1001",
        "frozenset_123",
        "bytearray",
        "dict_nested",
        "deep",
        "list_shared_list",
    ] {
        let v = case(name);
        let p = dumps(&v, Some(4)).unwrap();
        assert_eq!(protocol_of(&p), Some(4));
        assert!(loads(&p).unwrap() == v, "{name}");
    }
    // protocol 4 bytearray: REDUCE(builtins.bytearray, (b'\x01\x02\x03',))
    let p = dumps(&case("bytearray"), Some(4)).unwrap();
    assert_eq!(
        p,
        b"\x80\x04\x95\x24\x00\x00\x00\x00\x00\x00\x00\x8c\x08builtins\x94\x8c\x09bytearray\x94\x93\x94C\x03\x01\x02\x03\x94\x85\x94R\x94."
    );
}

#[test]
fn older_protocols_and_text_opcodes() {
    // protocol 2 (no framing, BINPUT memo) for the plain containers
    let v = case("dict_mixed");
    let p = dumps(&v, Some(2)).unwrap();
    assert_eq!(&p[..2], b"\x80\x02");
    assert!(loads(&p).unwrap() == v);
    let v = case("int_-1000000000000000000000000000000");
    assert!(loads(&dumps(&v, Some(2)).unwrap()).unwrap() == v);
    // protocol 0 text opcodes: INT / LONG / FLOAT / UNICODE / MARK LIST / DICT / PUT / GET
    let lst: Arg = vec![
        Arg::Int(-5),
        Arg::Bool(true),
        Arg::Float(2.5),
        Arg::from("h\u{e9}"),
    ]
    .into_arg();
    let p0 = dumps(&lst, Some(0)).unwrap();
    assert_eq!(p0, b"(lp0\nI-5\naI01\naF2.5\naVh\xe9\np1\na.");
    assert!(loads(&p0).unwrap() == lst);
    let text =
        b"(dp0\nVk\\u00e9y\np1\nL123456789012345678901234567890L\nsS'ab'\np2\nF1e3\nsg2\ng1\ns.";
    let back = loads(text).unwrap();
    let want = dict(Args::new()).unwrap();
    want.__setitem__(
        "k\u{e9}y",
        Arg::from_bigint("123456789012345678901234567890".parse().unwrap()),
    )
    .unwrap();
    want.__setitem__("ab", Arg::Float(1e3)).unwrap();
    want.__setitem__("ab", "k\u{e9}y").unwrap();
    assert!(back == want, "{back:?}");
    // STOP after a MARK-built tuple, POP / POP_MARK / DUP
    assert!(loads(b"(I1\nI2\nt.").unwrap() == Arg::Tuple(vec![Arg::Int(1), Arg::Int(2)].into()));
    assert!(loads(b"I1\nI2\n0.").unwrap() == Arg::Int(1));
    assert!(loads(b"I1\n(I2\nI3\n1.").unwrap() == Arg::Int(1));
    assert!(loads(b"]q\x00(I1\n2e.").unwrap() == vec![Arg::Int(1), Arg::Int(1)].into_arg());
    // SHORT_BINSTRING is latin-1 text
    assert!(loads(b"U\x02h\xe9.").unwrap() == "h\u{e9}");
    // builtins.set / frozenset / bytearray reduces (what older protocols emit)
    assert!(
        loads(b"cbuiltins\nset\n]q\x00(I1\nI2\nI3\ne\x85R.").unwrap()
            == set(args!(vec![Arg::Int(1), Arg::Int(2), Arg::Int(3)].into_arg())).unwrap()
    );
    assert!(
        loads(b"cbuiltins\nfrozenset\n]q\x00(I1\nI2\ne\x85R.").unwrap()
            == frozenset(args!(vec![Arg::Int(1), Arg::Int(2)].into_arg())).unwrap()
    );
    assert!(
        loads(b"cbuiltins\nbytearray\nC\x02\x01\x02\x85R.").unwrap()
            == bytearray(args!(laila::python::object::bytes([1u8, 2]))).unwrap()
    );
}

#[test]
fn unpickling_errors() {
    let err = |b: &[u8]| loads(b).unwrap_err();
    assert_eq!(
        err(b"\x80\x05").message,
        "pickle exhausted before seeing STOP"
    );
    assert_eq!(
        err(b"\x80\x05\x8c\x05ab").message,
        "pickle data was truncated"
    );
    assert_eq!(err(b"\x80\x05\x8c\x05ab").kind, ExcKind::UnpicklingError);
    assert_eq!(err(b"\x80\x06N.").message, "unsupported pickle protocol: 6");
    assert_eq!(err(b"\x80\x06N.").kind, ExcKind::ValueError);
    assert_eq!(
        err(b"\x80\x05h\x07.").message,
        "Memo value not found at index 7"
    );
    assert_eq!(err(b"\x80\x05t.").message, "could not find MARK");
    assert_eq!(err(b"\x80\x05.").message, "unpickling stack underflow");
    assert_eq!(err(b"\x80\x05\x99.").message, "invalid load key, '\u{99}'.");
    assert_eq!(err(b"\x80\x05N\x51.").message,
        "A load persistent id instruction was encountered, but no persistent_load function was specified.");
    assert_eq!(
        err(b"\x80\x05\x97.").message,
        "pickle stream refers to out-of-band data but no *buffers* argument was given"
    );
    assert_eq!(
        err(b"\x80\x05\x82\x01.").message,
        "unsupported pickle opcode 0x82"
    );
    // unknown globals are refused (never silently built)
    let e = err(b"\x80\x04\x8c\x02os\x94\x8c\x06system\x94\x93\x94\x8c\x02ls\x94\x85\x94R\x94.");
    assert_eq!(e.kind, ExcKind::UnpicklingError);
    assert_eq!(
        e.message,
        "global 'os.system' is forbidden: laila-rs cannot reconstruct arbitrary Python objects"
    );
    assert_eq!(err(b"cos\nsystem\n.").kind, ExcKind::UnpicklingError);
}

#[test]
fn dumps_errors_and_protocol_handling() {
    assert_eq!(DEFAULT_PROTOCOL, 5);
    assert_eq!(HIGHEST_PROTOCOL, 5);
    let e = dumps(&Arg::None, Some(6)).unwrap_err();
    assert_eq!(e.kind, ExcKind::ValueError);
    assert_eq!(e.message, "pickle protocol must be <= 5");
    assert_eq!(
        dumps(&Arg::None, Some(-1)).unwrap(),
        dumps(&Arg::None, None).unwrap()
    );
    assert_eq!(dumps(&Arg::None, Some(-1)).unwrap(), b"\x80\x05N.");
    let e = dumps(&callable(|| Arg::None), None).unwrap_err();
    assert_eq!(e.kind, ExcKind::PicklingError);
    assert_eq!(
        e.message,
        "Can't pickle <function <lambda>>: attribute lookup <lambda> on __main__ failed"
    );
    let e = dumps(&laila::python::object::bytes(b"x"), Some(2)).unwrap_err();
    assert_eq!(e.kind, ExcKind::PicklingError);
    // integers: LONG1 two's complement edge cases (CPython encode_long)
    for (v, want) in [
        (Arg::Int(128), &b"\x80\x05K\x80."[..]),
        (Arg::Int(-129), b"\x80\x05\x95\x06\x00\x00\x00\x00\x00\x00\x00J\x7f\xff\xff\xff."),
        (Arg::Int(2147483648), b"\x80\x05\x95\x08\x00\x00\x00\x00\x00\x00\x00\x8a\x05\x00\x00\x00\x80\x00."),
        (Arg::Int(-2147483649), b"\x80\x05\x95\x08\x00\x00\x00\x00\x00\x00\x00\x8a\x05\xff\xff\xff\x7f\xff."),
        (
            Arg::from_bigint("18446744073709551615".parse().unwrap()),
            b"\x80\x05\x95\x0c\x00\x00\x00\x00\x00\x00\x00\x8a\x09\xff\xff\xff\xff\xff\xff\xff\xff\x00.",
        ),
    ] {
        let got = dumps(&v, None).unwrap();
        assert!(got == want, "{v:?}: {}", first_diff(&got, want));
        assert!(loads(&got).unwrap() == v);
    }
}
